        // Panel switching
        

        // Initialize monthly trading chart
        function initMonthlyChart() {
            const ctx = document.getElementById('monthlyChart').getContext('2d');
            
            const monthlyData = timelineData.monthly_breakdown;
            const labels = Object.keys(monthlyData).sort();
            const data = labels.map(month => monthlyData[month]);
            
            new Chart(ctx, {
                type: 'line',
                data: {
                    labels: labels,
                    datasets: [{
                        label: 'Trades per Month',
                        data: data,
                        borderColor: '#667eea',
                        backgroundColor: 'rgba(102, 126, 234, 0.1)',
                        borderWidth: 3,
                        fill: true,
                        tension: 0.4
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            display: false
                        }
                    },
                    scales: {
                        y: {
                            beginAtZero: true,
                            ticks: {
                                stepSize: 1
                            }
                        }
                    }
                }
            });
        }

        // Initialize network graph
        function initNetworkGraph() {
            const container = document.getElementById('trade-network');
            
            if (!container || !networkData || !networkData.nodes) {
                console.error('Network container or data not available');
                return;
            }
            
            // Prepare nodes with better sizing and colors
            const maxTrades = Math.max(...Object.values(networkData.nodes).map(n => n.trade_count));
            const nodes = Object.keys(networkData.nodes).map(teamName => {
                const nodeData = networkData.nodes[teamName];
                const size = Math.max(30, (nodeData.trade_count / maxTrades) * 80);
                
                return {
                    id: teamName,
                    label: teamName,
                    size: size,
                    color: {
                        background: `hsl(${(nodeData.trade_count / maxTrades) * 60 + 200}, 40%, 35%)`,
                        border: '#606060',
                        highlight: {
                            background: '#0066cc',
                            border: '#66ccff'
                        }
                    },
                    font: { 
                        size: Math.max(12, size / 4),
                        color: '#e0e0e0',
                        strokeWidth: 2,
                        strokeColor: '#1a1a1a'
                    },
                    title: `${teamName}<br/>Trades: ${nodeData.trade_count}<br/>Players acquired: ${nodeData.players_acquired}<br/>Players given: ${nodeData.players_given}`
                };
            });
            
            // Prepare edges with better styling
            const maxWeight = Math.max(...Object.values(networkData.edges).map(e => e.weight));
            const edges = Object.keys(networkData.edges).map((edgeKey, index) => {
                const [team1, team2] = edgeKey.replace(/[()'"]/g, '').split(', ');
                const edgeData = networkData.edges[edgeKey];
                const width = Math.max(2, (edgeData.weight / maxWeight) * 10);
                const edgeId = `edge_${index}`;
                
                return {
                    id: edgeId, // Set ID when creating the edge
                    from: team1,
                    to: team2,
                    width: Math.max(5, width), // Make edges thicker for easier clicking
                    color: {
                        color: '#66ccff',
                        opacity: 0.7,
                        highlight: '#0066cc'
                    },
                    title: `${team1} ↔ ${team2}<br/>${edgeData.weight} trades<br/>${edgeData.total_players} players<br/>${edgeData.total_picks} picks<br/><strong>Click to see trade details!</strong>`,
                    smooth: {
                        type: 'continuous',
                        roundness: 0.1
                    },
                    selectionWidth: 8, // Make selection area larger
                    hoverWidth: 6 // Make hover area larger
                };
            });
            
            const data = { nodes: nodes, edges: edges };
            const options = {
                nodes: {
                    shape: 'circle',
                    borderWidth: 2,
                    shadow: true
                },
                edges: {
                    shadow: true,
                    smooth: true
                },
                physics: {
                    enabled: true,
                    solver: 'forceAtlas2Based',
                    forceAtlas2Based: {
                        gravitationalConstant: -50,
                        centralGravity: 0.01,
                        springLength: 200,
                        springConstant: 0.08,
                        damping: 0.4,
                        avoidOverlap: 1
                    },
                    stabilization: {
                        enabled: true,
                        iterations: 150,
                        updateInterval: 25
                    }
                },
                interaction: {
                    dragNodes: true,
                    dragView: true,
                    zoomView: true,
                    hover: true,
                    tooltipDelay: 300
                }
            };
            
            const network = new vis.Network(container, data, options);
            
            // Store edge data for click detection
            const edgeMap = {};
            edges.forEach(edge => {
                edgeMap[edge.id] = edge;
            });
            
            // Add click event for edges (connections between teams)
            network.on('click', function(params) {
                console.log('Network click:', params); // Debug log
                
                if (params.edges.length > 0) {
                    // User clicked on an edge - show trade details
                    const edgeId = params.edges[0];
                    console.log('Edge clicked:', edgeId); // Debug log
                    
                    const edge = edgeMap[edgeId];
                    if (edge) {
                        console.log('Found edge:', edge.from, '->', edge.to); // Debug log
                        showTeamTrades(edge.from, edge.to);
                    } else {
                        console.log('Edge not found in map'); // Debug log
                    }
                } else if (params.nodes.length > 0) {
                    // User clicked on a node - show team stats
                    const teamName = params.nodes[0];
                    const teamData = networkData.nodes[teamName];
                    console.log('Node clicked:', teamName); // Debug log
                    showTeamStats(teamName, teamData);
                }
            });
            
            // Also add selectEdge event as backup
            network.on('selectEdge', function(params) {
                console.log('Edge selected:', params); // Debug log
                if (params.edges.length > 0) {
                    const edgeId = params.edges[0];
                    const edge = edgeMap[edgeId];
                    if (edge) {
                        showTeamTrades(edge.from, edge.to);
                    }
                }
            });
            
            // Add double-click event as alternative
            network.on('doubleClick', function(params) {
                console.log('Network double-click:', params); // Debug log
                
                if (params.edges.length > 0) {
                    const edgeId = params.edges[0];
                    const edge = edgeMap[edgeId];
                    if (edge) {
                        console.log('Double-clicked edge:', edge.from, '->', edge.to);
                        showTeamTrades(edge.from, edge.to);
                    }
                } else if (params.nodes.length > 0) {
                    const teamName = params.nodes[0];
                    const teamData = networkData.nodes[teamName];
                    showTeamStats(teamName, teamData);
                }
            });
            
            // Add hover event to show edge info
            network.on('hoverEdge', function(params) {
                console.log('Edge hovered:', params.edge);
            });
        }

        // Show detailed trades between two teams
        function showTeamTrades(team1, team2) {
            // Find all trades between these two teams
            const teamTrades = timelineData.trades.filter(trade => {
                const teamsInTrade = trade.teams_involved;
                return teamsInTrade.includes(team1) && teamsInTrade.includes(team2);
            });
            
            if (teamTrades.length === 0) {
                showTradeModal(`
                    <div style="text-align: center; color: #666; padding: 20px;">
                        <h3>No Trades Found</h3>
                        <p>No trades found between ${team1} and ${team2}</p>
                    </div>
                `);
                return;
            }
            
            let tradesHTML = `
                <h3 style="margin-bottom: 20px; color: #e0e0e0; border-bottom: 2px solid #66ccff; padding-bottom: 10px;">
                    📊 ${team1} ↔ ${team2}
                    <span style="font-size: 0.9rem; color: #b0b0b0;">(${teamTrades.length} trade${teamTrades.length !== 1 ? 's' : ''})</span>
                </h3>
            `;
            
            teamTrades.forEach((trade, index) => {
                tradesHTML += `
                    <div class="trade-detail-item">
                        <div class="trade-detail-date">Trade #${index + 1} - ${trade.date}</div>
                        <div style="display: flex; gap: 20px; flex-wrap: wrap;">
                `;
                
                // Find the two teams involved in this trade
                const teamsInTrade = trade.trade_details.teams.filter(teamData => 
                    teamData.team === team1 || teamData.team === team2
                );
                
                teamsInTrade.forEach(teamData => {
                    const hasReceives = teamData.receives.players.length > 0 || teamData.receives.draft_picks.length > 0 || (teamData.receives.faab && teamData.receives.faab.length > 0);
                    const hasGives = teamData.gives && (teamData.gives.players.length > 0 || teamData.gives.draft_picks.length > 0 || (teamData.gives.faab && teamData.gives.faab.length > 0));
                    
                    if (hasReceives || hasGives) {
                        tradesHTML += `
                            <div style="flex: 1; min-width: 300px; background: #404040; padding: 20px; border-radius: 10px; border: 2px solid #66ccff; color: #e0e0e0;">
                                <h4 style="color: #66ccff; text-align: center; margin-bottom: 15px; font-size: 1.2rem;">${teamData.team}</h4>
                                
                                <div style="display: flex; gap: 15px;">
                                    <div style="flex: 1;">
                                        <div style="background: #2d5a2d; padding: 10px; border-radius: 5px; margin-bottom: 10px;">
                                            <strong style="color: #66ff66;">📥 Received:</strong>
                                        </div>
                                        <ul style="list-style: none; padding: 0; margin: 0;">
                        `;
                        
                        let hasReceivedAssets = false;
                        
                        // Show players
                        if (teamData.receives.players && teamData.receives.players.length > 0) {
                            teamData.receives.players.forEach(player => {
                                const playerImageUrl = `https://sleepercdn.com/content/nfl/players/thumb/${player.player_id || 'unknown'}.jpg`;
                                tradesHTML += `
                                    <li style="margin: 5px 0; padding: 8px; background: #606060; border-radius: 3px; color: #e0e0e0; display: flex; align-items: center; gap: 8px;">
                                        <img src="${playerImageUrl}" 
                                             style="width: 24px; height: 24px; border-radius: 50%; object-fit: cover;" 
                                             onerror="this.style.display='none'; this.nextElementSibling.innerHTML='🏈 ' + this.nextElementSibling.innerHTML"
                                             alt="${player.player}">
                                        <span>${player.player}</span>
                                    </li>`;
                                hasReceivedAssets = true;
                            });
                        }
                        
                        // Show draft picks
                        if (teamData.receives.draft_picks && teamData.receives.draft_picks.length > 0) {
                            teamData.receives.draft_picks.forEach(pick => {
                                let pickDisplay;
                                if (pick.pick_number && pick.player_name) {
                                    pickDisplay = `Pick #${pick.pick_number} (${pick.original_owner}'s ${pick.season} R${pick.round}) - ${pick.player_name}`;
                                } else {
                                    pickDisplay = pick.original_owner ? `${pick.original_owner}'s ${pick.season} Round ${pick.round} pick` : `${pick.season} Round ${pick.round} pick`;
                                }
                                tradesHTML += `<li style="margin: 5px 0; padding: 5px; background: #606060; border-radius: 3px; color: #e0e0e0;"><span style="color: #66ccff;">📋</span> ${pickDisplay}</li>`;
                                hasReceivedAssets = true;
                            });
                        }
                        
                        // Show FAAB received
                        if (teamData.receives.faab && teamData.receives.faab.length > 0) {
                            teamData.receives.faab.forEach(faab => {
                                tradesHTML += `<li style="margin: 5px 0; padding: 5px; background: #606060; border-radius: 3px; color: #e0e0e0;"><span style="color: #66ff66;">💰</span> $${faab.amount} FAAB</li>`;
                                hasReceivedAssets = true;
                            });
                        }
                        
                        if (!hasReceivedAssets) {
                            tradesHTML += `<li style="color: #b0b0b0; font-style: italic;">Nothing</li>`;
                        }
                        
                        tradesHTML += `
                                        </ul>
                                    </div>
                                    
                                    <div style="flex: 1;">
                                        <div style="background: #5a2d2d; padding: 10px; border-radius: 5px; margin-bottom: 10px;">
                                            <strong style="color: #ff6666;">📤 Gave:</strong>
                                        </div>
                                        <ul style="list-style: none; padding: 0; margin: 0;">
                        `;
                        
                        let hasGivenAssets = false;
                        
                        // Show players given
                        if (teamData.gives && teamData.gives.players && teamData.gives.players.length > 0) {
                            teamData.gives.players.forEach(player => {
                                const playerImageUrl = `https://sleepercdn.com/content/nfl/players/thumb/${player.player_id || 'unknown'}.jpg`;
                                tradesHTML += `
                                    <li style="margin: 5px 0; padding: 8px; background: #606060; border-radius: 3px; color: #e0e0e0; display: flex; align-items: center; gap: 8px;">
                                        <img src="${playerImageUrl}" 
                                             style="width: 24px; height: 24px; border-radius: 50%; object-fit: cover;" 
                                             onerror="this.style.display='none'; this.nextElementSibling.innerHTML='🏈 ' + this.nextElementSibling.innerHTML"
                                             alt="${player.player}">
                                        <span>${player.player}</span>
                                    </li>`;
                                hasGivenAssets = true;
                            });
                        }
                        
                        // Show draft picks given
                        if (teamData.gives && teamData.gives.draft_picks && teamData.gives.draft_picks.length > 0) {
                            teamData.gives.draft_picks.forEach(pick => {
                                let pickDisplay;
                                if (pick.pick_number && pick.player_name) {
                                    pickDisplay = `Pick #${pick.pick_number} (${pick.original_owner}'s ${pick.season} R${pick.round}) - ${pick.player_name}`;
                                } else {
                                    pickDisplay = pick.original_owner ? `${pick.original_owner}'s ${pick.season} Round ${pick.round} pick` : `${pick.season} Round ${pick.round} pick`;
                                }
                                tradesHTML += `<li style="margin: 5px 0; padding: 5px; background: #606060; border-radius: 3px; color: #e0e0e0;"><span style="color: #66ccff;">📋</span> ${pickDisplay}</li>`;
                                hasGivenAssets = true;
                            });
                        }
                        
                        // Show FAAB given
                        if (teamData.gives.faab && teamData.gives.faab.length > 0) {
                            teamData.gives.faab.forEach(faab => {
                                tradesHTML += `<li style="margin: 5px 0; padding: 5px; background: #606060; border-radius: 3px; color: #e0e0e0;"><span style="color: #ff6666;">💰</span> $${faab.amount} FAAB</li>`;
                                hasGivenAssets = true;
                            });
                        }
                        
                        if (!hasGivenAssets) {
                            tradesHTML += `<li style="color: #b0b0b0; font-style: italic;">Nothing</li>`;
                        }
                        
                        tradesHTML += `
                                        </ul>
                                    </div>
                                </div>
                            </div>
                        `;
                    }
                });
                
                tradesHTML += `
                        </div>
                    </div>
                `;
            });
            
            // Check if we're on network panel and have sidebar
            const detailsContent = document.getElementById('trade-details-content');
            if (detailsContent && document.getElementById('network-panel').classList.contains('active')) {
                // Show in sidebar
                detailsContent.innerHTML = tradesHTML;
                document.getElementById('trade-details-sidebar').scrollTop = 0;
            } else {
                // Show in modal
                showTradeModal(tradesHTML);
            }
        }
        
        // Show trade modal
        function showTradeModal(content) {
            const modal = document.getElementById('tradeModal');
            const modalContent = document.getElementById('tradeModalContent');
            modalContent.innerHTML = content;
            modal.style.display = 'block';
        }
        
        // Close trade modal
        function closeTradeModal() {
            document.getElementById('tradeModal').style.display = 'none';
        }
        
        // Show team statistics
        function showTeamStats(teamName, teamData) {
            const detailsContent = document.getElementById('trade-details-content');
            if (!detailsContent) return;
            
            const statsHTML = `
                <h4 style="margin-bottom: 15px; color: #e0e0e0;">${teamName} Statistics</h4>
                <div class="trade-detail-item">
                    <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; text-align: center;">
                        <div>
                            <div style="font-size: 1.5rem; font-weight: bold; color: #66ccff;">${teamData.trade_count}</div>
                            <div style="color: #b0b0b0;">Total Trades</div>
                        </div>
                        <div>
                            <div style="font-size: 1.5rem; font-weight: bold; color: #66ff66;">${teamData.players_acquired}</div>
                            <div style="color: #b0b0b0;">Players Acquired</div>
                        </div>
                        <div>
                            <div style="font-size: 1.5rem; font-weight: bold; color: #ff6666;">${teamData.players_given}</div>
                            <div style="color: #b0b0b0;">Players Given</div>
                        </div>
                        <div>
                            <div style="font-size: 1.5rem; font-weight: bold; color: #66ccff;">${teamData.draft_picks_acquired + teamData.draft_picks_given}</div>
                            <div style="color: #b0b0b0;">Draft Picks Traded</div>
                        </div>
                    </div>
                </div>
                <div style="margin-top: 15px; text-align: center; color: #b0b0b0;">
                    <em>Click on connections to see detailed trades between teams</em>
                </div>
            `;
            
            detailsContent.innerHTML = statsHTML;
        }

        // Player journey search
        async function searchPlayerJourney() {
            const playerName = document.getElementById('playerSearch').value.trim();
            const resultContainer = document.getElementById('playerJourneyResult');
            
            if (!playerName) {
                resultContainer.innerHTML = '<p style="text-align: center; color: #b0b0b0;">Please enter a player name to track their journey.</p>';
                return;
            }
            
            resultContainer.innerHTML = '<p style="text-align: center; color: #e0e0e0;">🔍 Searching for player journey...</p>';
            
            try {
                // Try to fetch real journey data from server with a shorter timeout
                let journeyData = null;
                
                try {
                    const controller = new AbortController();
                    const timeoutId = setTimeout(() => controller.abort(), 2000); // 2 second timeout
                    
                    const response = await fetch(`http://localhost:5000/player_journey/${getLeagueIdForYear('2024')}/${encodeURIComponent(playerName)}`, {
                        signal: controller.signal
                    });
                    clearTimeout(timeoutId);
                    
                    if (response.ok) {
                        journeyData = await response.json();
                    }
                } catch (fetchError) {
                    console.log('Server not available or timeout, falling back to local data:', fetchError);
                }
                
                if (journeyData && !journeyData.error) {
                    // Use the comprehensive journey data from the server
                    displayPlayerJourney(journeyData);
                } else {
                    // Quick fallback to local data search (just trade count)
                    displayLocalPlayerSearch(playerName);
                }
                
            } catch (error) {
                resultContainer.innerHTML = `
                    <div style="text-align: center; color: #ff6666; padding: 40px;">
                        <h3>❌ Error</h3>
                        <p>Failed to load player journey data.</p>
                        <p>Error: ${error.message}</p>
                    </div>
                `;
            }
        }
        
        function displayPlayerJourney(journeyData) {
            const resultContainer = document.getElementById('playerJourneyResult');
            
            let journeyHTML = `
                <div style="text-align: center; margin-bottom: 20px;">
                    <div style="margin-bottom: 15px;">
                        ${journeyData.player_image_url ? 
                            `<img src="${journeyData.player_image_url}" 
                                 style="width: 80px; height: 80px; border-radius: 50%; border: 3px solid #66ccff; object-fit: cover;" 
                                 onerror="this.style.display='none'"
                                 alt="${journeyData.player_name}">` : 
                            '🏈'
                        }
                    </div>
                    <h3>${journeyData.player_name}</h3>
                    <p style="color: #66ccff; font-size: 1.2rem;">
                        Total Trades: ${journeyData.total_trades} | 
                        Current Team: ${journeyData.current_team || 'Unknown'} |
                        Teams Involved: ${journeyData.teams_involved.length}
                    </p>
                </div>
            `;
            
            if (journeyData.timeline.length > 0) {
                journeyHTML += `
                    <div class="journey-legend">
                        <div class="legend-item">
                            <div class="legend-dot" style="background: #66ccff;"></div>
                            <span>Teams</span>
                        </div>
                        <div class="legend-item">
                            <div class="legend-dot" style="background: #ff6666;"></div>
                            <span>Trade</span>
                        </div>
                        <div class="legend-item">
                            <div class="legend-dot" style="background: #66ff66;"></div>
                            <span>Free Agent</span>
                        </div>
                        <div class="legend-item">
                            <div class="legend-dot" style="background: #ffcc66;"></div>
                            <span>Waiver</span>
                        </div>
                    </div>
                    <div id="playerJourneyNetwork" class="journey-network-container"></div>
                    <div id="journeyInfoPanel" class="journey-info-panel">
                        <h4 style="color: #66ccff; margin-bottom: 10px;">Journey Details</h4>
                        <p style="color: #b0b0b0;">Click on connections to see transaction details</p>
                    </div>
                `;
                
                resultContainer.innerHTML = journeyHTML;
                
                // Create the network visualization
                setTimeout(() => createPlayerJourneyNetwork(journeyData), 100);
            } else {
                journeyHTML += `
                    <div style="text-align: center; color: #b0b0b0; padding: 40px;">
                        <p>📊 No detailed journey data found for this player.</p>
                    </div>
                `;
                resultContainer.innerHTML = journeyHTML;
            }
        }
        
        function createPlayerJourneyNetwork(journeyData) {
            const container = document.getElementById('playerJourneyNetwork');
            if (!container) return;
            
            const nodes = [];
            const edges = [];
            const teams = new Set();
            
            // Add special nodes for non-team entities
            nodes.push({
                id: 'free_agency',
                label: 'Free\nAgency',
                color: {
                    background: '#666666',
                    border: '#888888'
                },
                font: { color: '#e0e0e0' },
                size: 30,
                shape: 'box'
            });
            
            nodes.push({
                id: 'waivers',
                label: 'Waivers',
                color: {
                    background: '#666666',
                    border: '#888888'
                },
                font: { color: '#e0e0e0' },
                size: 30,
                shape: 'box'
            });
            
            // Collect all teams from the journey
            journeyData.timeline.forEach(step => {
                if (step.to_team && step.to_team !== 'Free Agency' && step.to_team !== 'Waivers') {
                    teams.add(step.to_team);
                }
                if (step.from_team && step.from_team !== 'Free Agency' && step.from_team !== 'Waivers') {
                    teams.add(step.from_team);
                }
            });
            
            // Create team nodes with player image overlay
            teams.forEach(team => {
                const isCurrentTeam = team === journeyData.current_team;
                
                // Create a custom node with player image if available
                const nodeConfig = {
                    id: team,
                    label: team,
                    color: {
                        background: isCurrentTeam ? '#0066cc' : '#66ccff',
                        border: isCurrentTeam ? '#66ccff' : '#0066cc'
                    },
                    font: { 
                        color: '#e0e0e0',
                        size: isCurrentTeam ? 16 : 14,
                        bold: isCurrentTeam
                    },
                    size: isCurrentTeam ? 50 : 40,
                    title: isCurrentTeam ? `${team} (Current Team)` : team
                };
                
                // Add player image if available
                if (journeyData.player_image_url) {
                    nodeConfig.shape = 'circularImage';
                    nodeConfig.image = journeyData.player_image_url;
                    nodeConfig.size = isCurrentTeam ? 60 : 50;
                    nodeConfig.borderWidth = 3;
                    nodeConfig.borderWidthSelected = 4;
                }
                
                nodes.push(nodeConfig);
            });
            
            // Create edges for each transaction
            journeyData.timeline.forEach((step, index) => {
                let fromNode, toNode, edgeColor, edgeLabel;
                
                if (step.type === 'trade') {
                    fromNode = step.from_team;
                    toNode = step.to_team;
                    edgeColor = '#ff6666';
                    edgeLabel = `Trade #${step.trade_number}`;
                } else if (step.type === 'free_agent') {
                    fromNode = 'free_agency';
                    toNode = step.to_team;
                    edgeColor = '#66ff66';
                    edgeLabel = 'Free Agent';
                } else if (step.type === 'waiver') {
                    fromNode = 'waivers';
                    toNode = step.to_team;
                    edgeColor = '#ffcc66';
                    edgeLabel = 'Waiver Claim';
                }
                
                if (fromNode && toNode) {
                    edges.push({
                        id: `edge_${index}`,
                        from: fromNode,
                        to: toNode,
                        color: {
                            color: edgeColor,
                            highlight: edgeColor
                        },
                        width: 3,
                        arrows: 'to',
                        font: {
                            color: '#e0e0e0',
                            size: 12,
                            strokeWidth: 2,
                            strokeColor: '#1a1a1a'
                        },
                        label: edgeLabel,
                        title: `${step.date}<br/>${edgeLabel}<br/>Click for details`,
                        stepData: step
                    });
                }
            });
            
            const data = { nodes: nodes, edges: edges };
            const options = {
                nodes: {
                    borderWidth: 2,
                    shadow: true
                },
                edges: {
                    shadow: true,
                    smooth: {
                        type: 'continuous',
                        roundness: 0.2
                    },
                    arrowStrikethrough: false
                },
                physics: {
                    enabled: true,
                    solver: 'forceAtlas2Based',
                    forceAtlas2Based: {
                        gravitationalConstant: -100,
                        centralGravity: 0.05,
                        springLength: 150,
                        springConstant: 0.12,
                        damping: 0.4,
                        avoidOverlap: 1
                    },
                    stabilization: {
                        enabled: true,
                        iterations: 100
                    }
                },
                interaction: {
                    dragNodes: true,
                    dragView: true,
                    zoomView: true,
                    hover: true
                },
                layout: {
                    improvedLayout: true
                }
            };
            
            const network = new vis.Network(container, data, options);
            
            // Handle edge clicks to show transaction details
            network.on('click', function(params) {
                if (params.edges.length > 0) {
                    const edgeId = params.edges[0];
                    const edge = edges.find(e => e.id === edgeId);
                    
                    if (edge && edge.stepData) {
                        showJourneyStepDetails(edge.stepData, journeyData);
                    }
                }
            });
        }
        
        function showJourneyStepDetails(stepData, journeyData) {
            const infoPanel = document.getElementById('journeyInfoPanel');
            if (!infoPanel) return;
            
            let detailsHTML = `
                <h4 style="color: #66ccff; margin-bottom: 15px;">Transaction Details</h4>
                <div style="background: #404040; padding: 15px; border-radius: 8px; border: 1px solid #606060;">
                    <div style="display: flex; align-items: center; margin-bottom: 15px; gap: 15px;">
                        <div>
                            ${journeyData.player_image_url ? 
                                `<img src="${journeyData.player_image_url}" 
                                     style="width: 50px; height: 50px; border-radius: 50%; border: 2px solid #66ccff; object-fit: cover;" 
                                     onerror="this.style.display='none'"
                                     alt="${journeyData.player_name}">` : 
                                '<div style="width: 50px; height: 50px; background: #606060; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 20px;">🏈</div>'
                            }
                        </div>
                        <div>
                            <div style="font-weight: bold; color: #e0e0e0; font-size: 1.1rem;">${journeyData.player_name}</div>
                            <div style="color: #b0b0b0; font-size: 0.9rem;">${stepData.type === 'trade' ? 'Trade' : stepData.type === 'free_agent' ? 'Free Agent Pickup' : 'Waiver Claim'}</div>
                        </div>
                    </div>
                    <div style="margin-bottom: 10px;">
                        <strong style="color: #e0e0e0;">Date:</strong> <span style="color: #66ccff;">${stepData.date}</span>
                    </div>
            `;
            
            if (stepData.type === 'trade') {
                detailsHTML += `
                    <div style="margin-bottom: 10px;">
                        <strong style="color: #e0e0e0;">Trade #:</strong> <span style="color: #66ccff;">${stepData.trade_number}</span>
                    </div>
                    <div style="margin-bottom: 10px;">
                        <strong style="color: #e0e0e0;">From:</strong> <span style="color: #ff6666;">${stepData.from_team}</span>
                    </div>
                    <div style="margin-bottom: 10px;">
                        <strong style="color: #e0e0e0;">To:</strong> <span style="color: #66ff66;">${stepData.to_team}</span>
                    </div>
                `;
                
                if (stepData.trade_details.given_for && stepData.trade_details.given_for.length > 0) {
                    detailsHTML += `
                        <div>
                            <strong style="color: #e0e0e0;">Traded for:</strong><br/>
                            <ul style="margin: 5px 0 0 20px; color: #b0b0b0;">
                    `;
                    stepData.trade_details.given_for.forEach(asset => {
                        detailsHTML += `<li>${asset.name}</li>`;
                    });
                    detailsHTML += `</ul></div>`;
                } else {
                    detailsHTML += `<div><em style="color: #b0b0b0;">Part of larger trade package</em></div>`;
                }
            } else {
                detailsHTML += `
                    <div style="margin-bottom: 10px;">
                        <strong style="color: #e0e0e0;">Acquired from:</strong> <span style="color: #66ccff;">${stepData.from_team}</span>
                    </div>
                    <div>
                        <strong style="color: #e0e0e0;">New team:</strong> <span style="color: #66ff66;">${stepData.to_team}</span>
                    </div>
                `;
            }
            
            detailsHTML += `</div>`;
            infoPanel.innerHTML = detailsHTML;
        }
        
