// modules/network.js
/**
 * Network Module
 * Handles the trade network visualization using vis.js
 */


let network = null;

function initNetworkGraph() {
    const container = document.getElementById('trade-network');
    if (!container) return;
    
    // Create nodes with team data
    const nodes = new vis.DataSet();
    const edges = new vis.DataSet();
    
    // Add nodes
    Object.entries(networkData.nodes).forEach(([teamName, teamData]) => {
        nodes.add({
            id: teamName,
            label: `${teamName}\n${teamData.total_trades} trades`,
            value: teamData.total_trades,
            title: `${teamName}<br>Total Trades: ${teamData.total_trades}<br>Players Acquired: ${teamData.players_acquired}<br>Players Given: ${teamData.players_given}`,
            teamData: teamData
        });
    });
    
    // Add edges
    Object.entries(networkData.edges).forEach(([teamPair, edgeData]) => {
        // Parse team names from string format "('Team1', 'Team2')"
        const match = teamPair.match(/\('([^']+)', '([^']+)'\)/);
        if (match) {
            const [_, team1, team2] = match;
            edges.add({
                from: team1,
                to: team2,
                value: edgeData.weight,
                title: `${edgeData.weight} trades<br>${edgeData.total_players} players<br>${edgeData.total_picks} picks`,
                edgeData: edgeData
            });
        }
    });
    
    const data = { nodes, edges };
    
    const options = {
        nodes: {
            shape: 'dot',
            scaling: {
                min: 20,
                max: 50
            },
            font: {
                size: 12,
                color: '#e0e0e0'
            },
            color: {
                background: '#0066cc',
                border: '#004499',
                highlight: {
                    background: '#0088ff',
                    border: '#0066cc'
                }
            }
        },
        edges: {
            width: 2,
            scaling: {
                min: 1,
                max: 10
            },
            color: {
                color: '#666666',
                highlight: '#0066cc',
                hover: '#0066cc'
            },
            smooth: {
                type: 'continuous'
            }
        },
        interaction: {
            hover: true,
            tooltipDelay: 200,
            hideEdgesOnDrag: true
        },
        physics: {
            forceAtlas2Based: {
                gravitationalConstant: -50,
                centralGravity: 0.01,
                springLength: 100,
                springConstant: 0.08
            },
            maxVelocity: 50,
            solver: 'forceAtlas2Based',
            timestep: 0.35,
            stabilization: {
                enabled: true,
                iterations: 1000,
                updateInterval: 10
            }
        }
    };
    
    // Create network
    network = new vis.Network(container, data, options);
    
    // Add click handlers
    network.on('click', function(params) {
        if (params.nodes.length > 0) {
            const nodeId = params.nodes[0];
            const node = nodes.get(nodeId);
            if (node && node.teamData) {
                showTeamStats(nodeId, node.teamData);
            }
        }
    });
    
    // Handle edge clicks and double-clicks
    let clickTimer = null;
    let clickDelay = 300;
    
    network.on('selectEdge', function(params) {
        if (clickTimer === null) {
            clickTimer = setTimeout(() => {
                // Single click
                handleEdgeClick(params);
                clickTimer = null;
            }, clickDelay);
        } else {
            // Double click
            clearTimeout(clickTimer);
            clickTimer = null;
            handleEdgeClick(params);
        }
    });
    
    function handleEdgeClick(params) {
        if (params.edges.length > 0) {
            const edgeId = params.edges[0];
            const edge = edges.get(edgeId);
            if (edge) {
                const team1 = edge.from;
                const team2 = edge.to;
                showTeamTrades(team1, team2);
            }
        }
    }
}

function showTeamStats(teamName, teamData) {
    const detailsContent = document.getElementById('trade-details-content');
    if (!detailsContent) return;
    
    let html = `
        <h4>${teamName} Statistics</h4>
        <div class="team-stats">
            <p><strong>Total Trades:</strong> ${teamData.total_trades}</p>
            <p><strong>Players Acquired:</strong> ${teamData.players_acquired}</p>
            <p><strong>Players Given:</strong> ${teamData.players_given}</p>
            <p><strong>Avg Players/Trade:</strong> ${teamData.avg_players_per_trade.toFixed(2)}</p>
            <p><strong>Most Frequent Partner:</strong> ${teamData.most_frequent_partner}</p>
            <p><strong>Trading Partners:</strong> ${teamData.partners.join(', ')}</p>
        </div>
    `;
    
    detailsContent.innerHTML = html;
}

function showTeamTrades(team1, team2) {
    const detailsContent = document.getElementById('trade-details-content');
    if (!detailsContent) return;
    
    // Find the edge data
    let edgeData = null;
    let edgeKey = null;
    
    // Try both possible key formats
    const key1 = `('${team1}', '${team2}')`;
    const key2 = `('${team2}', '${team1}')`;
    
    if (networkData.edges[key1]) {
        edgeData = networkData.edges[key1];
        edgeKey = key1;
    } else if (networkData.edges[key2]) {
        edgeData = networkData.edges[key2];
        edgeKey = key2;
    }
    
    if (!edgeData) {
        detailsContent.innerHTML = '<p>No trades found between these teams.</p>';
        return;
    }
    
    let html = `
        <h4>${team1} ↔ ${team2}</h4>
        <p><strong>Total Trades:</strong> ${edgeData.weight}</p>
        <p><strong>Players Traded:</strong> ${edgeData.total_players}</p>
        <p><strong>Draft Picks Traded:</strong> ${edgeData.total_picks}</p>
        <div class="trade-list">
    `;
    
    edgeData.trades.forEach((trade, index) => {
        html += `
            <div class="trade-item-small">
                <h5>Trade ${index + 1} - ${trade.date}</h5>
        `;
        
        trade.details.teams.forEach(team => {
            if (team.team === team1 || team.team === team2) {
                html += `<div class="team-section"><strong>${team.team}</strong>`;
                
                if (team.gives.players.length > 0) {
                    html += '<div class="gives">Gave: ';
                    html += team.gives.players.map(p => p.player).join(', ');
                    html += '</div>';
                }
                
                if (team.receives.players.length > 0) {
                    html += '<div class="receives">Received: ';
                    html += team.receives.players.map(p => p.player).join(', ');
                    html += '</div>';
                }
                
                if (team.gives.draft_picks.length > 0) {
                    html += '<div class="gives">Gave picks: ';
                    html += team.gives.draft_picks.map(p => 
                        `${p.season} Round ${p.round}${p.player_name ? ` (#${p.pick_number} - ${p.player_name})` : ''}`
                    ).join(', ');
                    html += '</div>';
                }
                
                if (team.receives.draft_picks.length > 0) {
                    html += '<div class="receives">Received picks: ';
                    html += team.receives.draft_picks.map(p => 
                        `${p.season} Round ${p.round}${p.player_name ? ` (#${p.pick_number} - ${p.player_name})` : ''}`
                    ).join(', ');
                    html += '</div>';
                }
                
                html += '</div>';
            }
        });
        
        html += '</div>';
    });
    
    html += '</div>';
    detailsContent.innerHTML = html;
}

// Export to window for onclick handlers
window.initNetworkGraph = initNetworkGraph;
window.showTeamTrades = showTeamTrades;

// modules/tradeHistory.js
/**
 * Trade History Module
 * Handles trade history timeline, filtering, and grading
 */


function initializeTradeHistory() {
    // Populate team filter dropdown
    populateTeamFilter();
    
    // Add trading graders to all trades
    addTradingGradersToAllTrades();
    
    // Load saved grades
    loadTradeGrades();
    
    // Load average ratings from Firebase
    loadAverageRatings();
}

function addTradingGradersToAllTrades() {
    const tradeItems = document.querySelectorAll('.trade-item');
    tradeItems.forEach((item, index) => {
        // Check if grader already exists
        if (!item.querySelector('.trade-grade-container')) {
            const graderHtml = `
                <div class="trade-grade-container">
                    <div style="margin-bottom: 8px; color: #e0e0e0; font-weight: 600;">👤 Your Trade Grade:</div>
                    <input type="range" min="0" max="100" value="50" 
                           class="trade-grade-slider" 
                           id="trade-grade-${index}"
                           onchange="updateTradeGrade('${index}', this.value)">
                    <div class="trade-grade-labels">
                        <span>Team 1 Won</span>
                        <span>Even</span>
                        <span>Team 2 Won</span>
                    </div>
                    <div class="trade-grade-result" id="trade-result-${index}">
                        <span style="color: #999999;">Move slider to grade</span>
                    </div>
                </div>
            `;
            item.insertAdjacentHTML('beforeend', graderHtml);
        }
    });
}

function populateTeamFilter() {
    const filterSelect = document.getElementById('team-filter');
    if (!filterSelect) return;
    
    // Get all unique team names from trade items
    const teams = new Set();
    document.querySelectorAll('.trade-teams .team-side h4').forEach(el => {
        teams.add(el.textContent.trim());
    });
    
    // Clear existing options except "All Teams"
    filterSelect.innerHTML = '<option value="">All Teams</option>';
    
    // Add team options
    Array.from(teams).sort().forEach(team => {
        const option = document.createElement('option');
        option.value = team;
        option.textContent = team;
        filterSelect.appendChild(option);
    });
}

function filterTradesByTeam() {
    const filterValue = document.getElementById('team-filter').value;
    const tradeItems = document.querySelectorAll('.trade-item');
    
    tradeItems.forEach(item => {
        if (!filterValue) {
            item.style.display = 'block';
        } else {
            const teamNames = Array.from(item.querySelectorAll('.team-side h4')).map(el => el.textContent.trim());
            if (teamNames.includes(filterValue)) {
                item.style.display = 'block';
            } else {
                item.style.display = 'none';
            }
        }
    });
}

function resetTradeFilter() {
    document.getElementById('team-filter').value = '';
    filterTradesByTeam();
}

function updateTradeGrade(tradeIndex, value) {
    const slider = document.getElementById(`trade-grade-${tradeIndex}`);
    const resultDiv = document.getElementById(`trade-result-${tradeIndex}`);
    
    if (!slider || !resultDiv) return;
    
    // Get teams from the trade item
    const tradeItem = slider.closest('.trade-item');
    const teams = tradeItem.querySelectorAll('.team-side h4');
    const team1 = teams[0]?.textContent || 'Team 1';
    const team2 = teams[1]?.textContent || 'Team 2';
    
    // Determine result based on value
    let resultText = '';
    let resultColor = '';
    
    if (value < 40) {
        resultText = `You say: ${team1} won`;
        resultColor = '#66ff66';
    } else if (value > 60) {
        resultText = `You say: ${team2} won`;
        resultColor = '#ff6666';
    } else {
        resultText = 'You say: Even trade';
        resultColor = '#ffcc66';
    }
    
    resultDiv.innerHTML = `<span style="color: ${resultColor};">${resultText}</span>`;
    
    // Save the grade
    saveTradeGrade(tradeIndex, value);
}

function saveTradeGrade(tradeIndex, gradeValue) {
    // Save to localStorage
    const grades = JSON.parse(localStorage.getItem('tradeGrades') || '{}');
    grades[tradeIndex] = gradeValue;
    localStorage.setItem('tradeGrades', JSON.stringify(grades));
    
    // Save to Firebase if available
    const userName = getUserName();
    saveTradeGradeToFirebase(tradeIndex, gradeValue, userName);
}

function loadTradeGrades() {
    const grades = JSON.parse(localStorage.getItem('tradeGrades') || '{}');
    
    Object.entries(grades).forEach(([index, value]) => {
        const slider = document.getElementById(`trade-grade-${index}`);
        if (slider) {
            slider.value = value;
            // Use display-only function to avoid infinite loop
            updateTradeGradeDisplay(index, value);
        }
    });
}

function getUserName() {
    let userName = localStorage.getItem('userName');
    if (!userName) {
        userName = prompt('Please enter your name for trade grading:') || 'Anonymous';
        localStorage.setItem('userName', userName);
    }
    return userName;
}

function generateTradingSummary() {
    const container = document.getElementById('trading-summary-container');
    if (!container) return;
    
    const db = getDb();
    if (!db) {
        container.innerHTML = '<p style="color: #ff6666;">❌ Firebase not connected. Summary unavailable.</p>';
        return;
    }
    
    // Show loading state
    container.innerHTML = '<p style="color: #999;">Loading trading summary...</p>';
    
    // Render the table (will be updated with data later)
    renderTradingSummaryTable();
}

function renderTradingSummaryTable() {
    const container = document.getElementById('trading-summary-container');
    if (!container) return;
    
    const html = `
        <table style="width: 100%; border-collapse: collapse; margin-bottom: 20px;">
            <thead>
                <tr style="background: #0066cc; color: white;">
                    <th style="padding: 10px; border: 1px solid #606060; cursor: pointer;" onclick="sortTradingTable('team')">Team ↕</th>
                    <th style="padding: 10px; border: 1px solid #606060; cursor: pointer;" onclick="sortTradingTable('trades')">Trades ↕</th>
                    <th style="padding: 10px; border: 1px solid #606060; cursor: pointer;" onclick="sortTradingTable('winRate')">Win Rate ↕</th>
                    <th style="padding: 10px; border: 1px solid #606060; cursor: pointer;" onclick="sortTradingTable('avgGrade')">Avg Grade ↕</th>
                    <th style="padding: 10px; border: 1px solid #606060;">Good Trades</th>
                    <th style="padding: 10px; border: 1px solid #606060;">Bad Trades</th>
                </tr>
            </thead>
            <tbody id="trading-summary-tbody">
                <tr>
                    <td colspan="6" style="text-align: center; padding: 20px; color: #999;">
                        Calculating team statistics...
                    </td>
                </tr>
            </tbody>
        </table>
        <p style="font-size: 0.9em; color: #999;">
            <strong>Note:</strong> Based on community trade grades. Win = grade < 40, Loss = grade > 60
        </p>
    `;
    
    container.innerHTML = html;
    
    // Calculate and display stats
    calculateTeamTradingStats();
}

let sortColumn = 'trades';
let sortDirection = 'desc';

function sortTradingTable(column) {
    if (sortColumn === column) {
        sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
        sortColumn = column;
        sortDirection = 'desc';
    }
    
    calculateTeamTradingStats();
}

function calculateTeamTradingStats() {
    const teamStats = {};
    
    // Initialize team stats
    document.querySelectorAll('.trade-item').forEach((item, index) => {
        const teams = Array.from(item.querySelectorAll('.team-side h4')).map(el => el.textContent.trim());
        teams.forEach(team => {
            if (!teamStats[team]) {
                teamStats[team] = {
                    totalTrades: 0,
                    wins: 0,
                    losses: 0,
                    evens: 0,
                    totalGrade: 0,
                    gradedTrades: 0
                };
            }
            teamStats[team].totalTrades++;
        });
    });
    
    // Count wins/losses based on grades
    document.querySelectorAll('.trade-item').forEach((item, index) => {
        const slider = item.querySelector(`#trade-grade-${index}`);
        if (slider && slider.value !== '50') {
            const teams = Array.from(item.querySelectorAll('.team-side h4')).map(el => el.textContent.trim());
            const value = parseInt(slider.value);
            
            if (teams.length >= 2) {
                const team1 = teams[0];
                const team2 = teams[1];
                
                if (value < 40) {
                    // Team 1 won
                    teamStats[team1].wins++;
                    teamStats[team2].losses++;
                    teamStats[team1].totalGrade += (100 - value);
                    teamStats[team2].totalGrade += value;
                } else if (value > 60) {
                    // Team 2 won
                    teamStats[team2].wins++;
                    teamStats[team1].losses++;
                    teamStats[team2].totalGrade += (100 - value);
                    teamStats[team1].totalGrade += value;
                } else {
                    // Even trade
                    teamStats[team1].evens++;
                    teamStats[team2].evens++;
                    teamStats[team1].totalGrade += 50;
                    teamStats[team2].totalGrade += 50;
                }
                
                teamStats[team1].gradedTrades++;
                teamStats[team2].gradedTrades++;
            }
        }
    });
    
    // Convert to array and sort
    let sortedTeams = Object.entries(teamStats).map(([team, stats]) => {
        const winRate = stats.gradedTrades > 0 ? (stats.wins / stats.gradedTrades * 100).toFixed(1) : '0.0';
        const avgGrade = stats.gradedTrades > 0 ? (stats.totalGrade / stats.gradedTrades).toFixed(1) : '50.0';
        
        return {
            team,
            trades: stats.totalTrades,
            winRate: parseFloat(winRate),
            avgGrade: parseFloat(avgGrade),
            wins: stats.wins,
            losses: stats.losses,
            evens: stats.evens,
            gradedTrades: stats.gradedTrades
        };
    });
    
    // Sort based on current column
    sortedTeams.sort((a, b) => {
        let aVal, bVal;
        
        switch (sortColumn) {
            case 'team':
                aVal = a.team;
                bVal = b.team;
                break;
            case 'trades':
                aVal = a.trades;
                bVal = b.trades;
                break;
            case 'winRate':
                aVal = a.winRate;
                bVal = b.winRate;
                break;
            case 'avgGrade':
                aVal = a.avgGrade;
                bVal = b.avgGrade;
                break;
            default:
                aVal = a.trades;
                bVal = b.trades;
        }
        
        if (sortColumn === 'team') {
            return sortDirection === 'asc' ? aVal.localeCompare(bVal) : bVal.localeCompare(aVal);
        } else {
            return sortDirection === 'asc' ? aVal - bVal : bVal - aVal;
        }
    });
    
    // Update table
    const tbody = document.getElementById('trading-summary-tbody');
    if (!tbody) return;
    
    tbody.innerHTML = sortedTeams.map(team => {
        const gradeClass = getGradeClass(team.avgGrade);
        const gradeText = getGradeText(team.avgGrade);
        
        return `
            <tr>
                <td style="padding: 10px; border: 1px solid #606060; font-weight: bold;">${team.team}</td>
                <td style="padding: 10px; border: 1px solid #606060; text-align: center;">${team.trades}</td>
                <td style="padding: 10px; border: 1px solid #606060; text-align: center;">
                    ${team.gradedTrades > 0 ? `${team.winRate}%` : '-'}
                    ${team.gradedTrades > 0 ? `<br><small>(${team.gradedTrades} graded)</small>` : ''}
                </td>
                <td style="padding: 10px; border: 1px solid #606060; text-align: center;" class="${gradeClass}">
                    ${team.gradedTrades > 0 ? `${team.avgGrade} (${gradeText})` : '-'}
                </td>
                <td style="padding: 10px; border: 1px solid #606060; text-align: center; color: #66ff66;">
                    ${team.wins}
                </td>
                <td style="padding: 10px; border: 1px solid #606060; text-align: center; color: #ff6666;">
                    ${team.losses}
                </td>
            </tr>
        `;
    }).join('');
}

function getGradeClass(averageScore) {
    if (averageScore >= 70) return 'grade-a';
    if (averageScore >= 60) return 'grade-b';
    if (averageScore >= 50) return 'grade-c';
    if (averageScore >= 40) return 'grade-d';
    return 'grade-f';
}

function getGradeText(averageScore) {
    if (averageScore >= 70) return 'A';
    if (averageScore >= 60) return 'B';
    if (averageScore >= 50) return 'C';
    if (averageScore >= 40) return 'D';
    return 'F';
}

function refreshTradingSummary() {
    generateTradingSummary();
}

function updateSummaryWithAverages(allRatings) {
    // Recalculate team stats with Firebase data
    const teamStats = {};
    
    // Initialize team stats
    document.querySelectorAll('.trade-item').forEach((item, index) => {
        const teams = Array.from(item.querySelectorAll('.team-side h4')).map(el => el.textContent.trim());
        teams.forEach(team => {
            if (!teamStats[team]) {
                teamStats[team] = {
                    totalTrades: 0,
                    wins: 0,
                    losses: 0,
                    evens: 0,
                    totalGrade: 0,
                    gradedTrades: 0
                };
            }
            teamStats[team].totalTrades++;
        });
    });
    
    // Count wins/losses based on Firebase ratings
    document.querySelectorAll('.trade-item').forEach((item, index) => {
        const dateEl = item.querySelector('.trade-date');
        const summaryEl = item.querySelector('.trade-summary strong');
        const tradeId = `${dateEl?.textContent.trim()}_${summaryEl?.textContent.trim()}`.replace(/[^a-zA-Z0-9]/g, '_');
        
        if (allRatings[tradeId]) {
            const teams = Array.from(item.querySelectorAll('.team-side h4')).map(el => el.textContent.trim());
            const value = allRatings[tradeId].average;
            
            if (teams.length >= 2) {
                const team1 = teams[0];
                const team2 = teams[1];
                
                if (value < 40) {
                    // Team 1 won
                    teamStats[team1].wins++;
                    teamStats[team2].losses++;
                    teamStats[team1].totalGrade += (100 - value);
                    teamStats[team2].totalGrade += value;
                } else if (value > 60) {
                    // Team 2 won
                    teamStats[team2].wins++;
                    teamStats[team1].losses++;
                    teamStats[team2].totalGrade += (100 - value);
                    teamStats[team1].totalGrade += value;
                } else {
                    // Even trade
                    teamStats[team1].evens++;
                    teamStats[team2].evens++;
                    teamStats[team1].totalGrade += 50;
                    teamStats[team2].totalGrade += 50;
                }
                
                teamStats[team1].gradedTrades++;
                teamStats[team2].gradedTrades++;
            }
        }
    });
    
    // Re-render the table with updated stats
    calculateTeamTradingStats();
}

// Export to window for onclick handlers
window.updateTradeGrade = updateTradeGrade;
window.filterTradesByTeam = filterTradesByTeam;
window.resetTradeFilter = resetTradeFilter;
window.sortTradingTable = sortTradingTable;
window.refreshTradingSummary = refreshTradingSummary;

// modules/matchups.js
/**
 * Matchups Module
 * Handles matchup display and filtering
 */


function showMatchupYear() {
    console.log('🎯 showMatchupYear called');
    const yearSelect = document.getElementById('matchupYearSelect');
    const selectedYear = yearSelect ? yearSelect.value : '2024';
    
    console.log('Selected year:', selectedYear);
    
    // Hide all year matchups first
    const yearMatchups = document.querySelectorAll('.year-matchups');
    console.log('Found year matchups:', yearMatchups.length);
    
    yearMatchups.forEach(yearDiv => {
        yearDiv.style.display = 'none';
    });
    
    // Show selected year
    const selectedYearDiv = document.querySelector(`.year-matchups[data-year="${selectedYear}"]`);
    if (selectedYearDiv) {
        selectedYearDiv.style.display = 'block';
        console.log('Showing year:', selectedYear);
        
        // Re-attach click handlers for this year's matchups
        const matchupBreakdowns = getMatchupBreakdowns();
        if (matchupBreakdowns && matchupBreakdowns[selectedYear]) {
            addMatchupClickHandlers();
        }
    } else {
        console.error('Year div not found for:', selectedYear);
    }
    
    // Clear any active filters
    clearHeadToHeadFilter();
}

function filterHeadToHead(team1, team2, showNotification = true) {
    console.log('Filtering head-to-head:', team1, 'vs', team2);
    
    // Show all matchups first
    document.querySelectorAll('.matchup-item').forEach(item => {
        item.style.display = 'block';
    });
    
    // Then hide those that don't match
    document.querySelectorAll('.matchup-item').forEach(item => {
        const teamElements = item.querySelectorAll('.team-name');
        const teams = Array.from(teamElements).map(el => el.textContent.trim());
        
        if (!teams.includes(team1) || !teams.includes(team2)) {
            item.style.display = 'none';
        }
    });
    
    // Update active filter display
    const filterDisplay = document.getElementById('active-filter');
    if (filterDisplay) {
        filterDisplay.innerHTML = `
            <div style="background: #0066cc; color: white; padding: 10px; border-radius: 5px; margin: 10px 0;">
                Showing: ${team1} vs ${team2} 
                <button onclick="clearHeadToHeadFilter()" style="margin-left: 10px; background: white; color: #0066cc; border: none; padding: 2px 8px; border-radius: 3px; cursor: pointer;">Clear Filter</button>
            </div>
        `;
    }
    
    if (showNotification) {
        // Show a temporary notification
        const notification = document.createElement('div');
        notification.style.cssText = 'position: fixed; top: 20px; right: 20px; background: #0066cc; color: white; padding: 15px; border-radius: 5px; z-index: 1000;';
        notification.textContent = `Filtered to ${team1} vs ${team2}`;
        document.body.appendChild(notification);
        setTimeout(() => notification.remove(), 3000);
    }
}

function clearHeadToHeadFilter() {
    // Show all matchups
    document.querySelectorAll('.matchup-item').forEach(item => {
        item.style.display = 'block';
    });
    
    // Clear active filter display
    const filterDisplay = document.getElementById('active-filter');
    if (filterDisplay) {
        filterDisplay.innerHTML = '';
    }
}

function loadMatchupBreakdowns() {
    console.log('Loading matchup breakdowns...');
    const matchupBreakdowns = getMatchupBreakdowns();
    if (matchupBreakdowns) {
        console.log('Matchup breakdowns loaded:', Object.keys(matchupBreakdowns));
        // Add click handlers
        addMatchupClickHandlers();
    } else {
        console.error('Matchup breakdowns not found!');
    }
}

function togglePlayerBreakdowns() {
    const checkbox = document.getElementById('toggleBreakdowns');
    const isEnabled = checkbox ? checkbox.checked : false;
    
    // Store preference
    localStorage.setItem('showPlayerBreakdowns', isEnabled);
    
    if (isEnabled) {
        console.log('Enabling matchup click handlers...');
        addMatchupClickHandlers();
        
        // Show notification
        const notification = document.createElement('div');
        notification.style.cssText = 'position: fixed; top: 20px; right: 20px; background: #4CAF50; color: white; padding: 15px; border-radius: 5px; z-index: 1000;';
        notification.textContent = 'Player breakdowns enabled - click any matchup to see details';
        document.body.appendChild(notification);
        setTimeout(() => notification.remove(), 3000);
    } else {
        console.log('Disabling matchup click handlers...');
        removeMatchupClickHandlers();
    }
}

function addMatchupClickHandlers() {
    console.log('Adding matchup click handlers...');
    const matchupItems = document.querySelectorAll('.matchup-item');
    console.log('Found matchup items:', matchupItems.length);
    
    matchupItems.forEach(item => {
        // Remove existing listener to avoid duplicates
        item.removeEventListener('click', handleMatchupClick);
        // Add new listener
        item.addEventListener('click', handleMatchupClick);
        item.style.cursor = 'pointer';
        item.title = 'Click to see player breakdowns';
    });
}

function removeMatchupClickHandlers() {
    const matchupItems = document.querySelectorAll('.matchup-item');
    matchupItems.forEach(item => {
        item.removeEventListener('click', handleMatchupClick);
        item.style.cursor = 'default';
        item.title = '';
    });
}

function handleMatchupClick(event) {
    // Prevent clicking on buttons from triggering this
    if (event.target.tagName === 'BUTTON') {
        return;
    }
    
    const matchupItem = event.currentTarget;
    
    // Extract matchup information
    const weekText = matchupItem.querySelector('h4')?.textContent || '';
    const weekMatch = weekText.match(/Week (\d+)/);
    const week = weekMatch ? weekMatch[1] : null;
    
    const teams = matchupItem.querySelectorAll('.team-name');
    const scores = matchupItem.querySelectorAll('.team-score');
    
    if (teams.length >= 2 && scores.length >= 2 && week) {
        const team1Name = teams[0].textContent.trim();
        const team2Name = teams[1].textContent.trim();
        const team1Score = scores[0].textContent.trim();
        const team2Score = scores[1].textContent.trim();
        
        // Get the year from the parent container
        const yearContainer = matchupItem.closest('.year-matchups');
        const year = yearContainer ? yearContainer.getAttribute('data-year') : '2024';
        
        // Get the matchup ID from the data attribute
        const matchupId = matchupItem.getAttribute('data-matchup-id');
        
        console.log('Clicked matchup:', {
            year,
            week,
            teams: [team1Name, team2Name],
            scores: [team1Score, team2Score],
            matchupId
        });
        
        // Get league ID from the year mapping
        const leagueIdByYear = getLeagueIdByYear();
        const leagueId = leagueIdByYear && leagueIdByYear[year];
        
        if (leagueId) {
            showMatchupBreakdownModal(leagueId, week, [team1Name, team2Name], [team1Score, team2Score], matchupId);
        } else {
            console.error('League ID not found for year:', year);
        }
    }
}

function showMatchupBreakdownModal(leagueId, week, teams, scores, matchupId) {
    console.log('Showing breakdown modal:', { leagueId, week, teams, scores, matchupId });
    
    // Create modal if it doesn't exist
    let modal = document.getElementById('matchupBreakdownModal');
    if (!modal) {
        modal = createBreakdownModal();
    }
    
    // Update modal content
    const modalBody = modal.querySelector('.modal-body');
    modalBody.innerHTML = '<p>Loading player breakdowns...</p>';
    
    // Get year from league ID
    let year = null;
    const leagueIdByYear = getLeagueIdByYear();
    if (leagueIdByYear) {
        for (const [y, id] of Object.entries(leagueIdByYear)) {
            if (id === leagueId) {
                year = y;
                break;
            }
        }
    }
    
    // Update modal title
    const modalTitle = modal.querySelector('.modal-title');
    modalTitle.textContent = `Week ${week} Breakdown - ${teams[0]} (${scores[0]}) vs ${teams[1]} (${scores[1]})`;
    
    // Get breakdown data
    const matchupBreakdowns = getMatchupBreakdowns();
    if (matchupBreakdowns && year && matchupBreakdowns[year]) {
        const weekData = matchupBreakdowns[year][`week_${week}`];
        if (weekData) {
            // Find the specific matchup
            let matchupData = null;
            for (const matchup of weekData) {
                if (matchup.team_1.name === teams[0] && matchup.team_2.name === teams[1]) {
                    matchupData = matchup;
                    break;
                } else if (matchup.team_1.name === teams[1] && matchup.team_2.name === teams[0]) {
                    // Swap teams to match order
                    matchupData = {
                        team_1: matchup.team_2,
                        team_2: matchup.team_1
                    };
                    break;
                }
            }
            
            if (matchupData) {
                const html = generateBreakdownHTML(matchupData, week, teams);
                modalBody.innerHTML = html;
            } else {
                modalBody.innerHTML = '<p>Breakdown data not found for this matchup.</p>';
            }
        } else {
            modalBody.innerHTML = '<p>No breakdown data available for this week.</p>';
        }
    } else {
        modalBody.innerHTML = '<p>Breakdown data not loaded.</p>';
    }
    
    // Show modal
    modal.style.display = 'block';
    document.body.style.overflow = 'hidden';
}

function createBreakdownModal() {
    const modal = document.createElement('div');
    modal.id = 'matchupBreakdownModal';
    modal.className = 'modal';
    modal.innerHTML = `
        <div class="modal-content" style="width: 90%; max-width: 1000px;">
            <div class="modal-header">
                <h2 class="modal-title">Matchup Breakdown</h2>
                <span class="close" onclick="closeBreakdownModal()">&times;</span>
            </div>
            <div class="modal-body">
                <!-- Content will be dynamically inserted -->
            </div>
        </div>
    `;
    
    document.body.appendChild(modal);
    
    // Close modal when clicking outside
    modal.addEventListener('click', (e) => {
        if (e.target === modal) {
            closeBreakdownModal();
        }
    });
    
    return modal;
}

function generateBreakdownHTML(teams, week, teamNames) {
    let html = '<div class="breakdown-container">';
    
    // Team comparison header
    html += `
        <div class="team-comparison" style="display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 20px;">
            <div class="team-breakdown">
                <h3 style="text-align: center; color: #0066cc;">${teams.team_1.name}</h3>
                <div class="score-display" style="text-align: center; font-size: 2em; font-weight: bold; color: ${teams.team_1.score > teams.team_2.score ? '#4CAF50' : '#999'};">
                    ${teams.team_1.score}
                </div>
            </div>
            <div class="team-breakdown">
                <h3 style="text-align: center; color: #0066cc;">${teams.team_2.name}</h3>
                <div class="score-display" style="text-align: center; font-size: 2em; font-weight: bold; color: ${teams.team_2.score > teams.team_1.score ? '#4CAF50' : '#999'};">
                    ${teams.team_2.score}
                </div>
            </div>
        </div>
    `;
    
    // Player breakdowns
    html += '<div style="display: grid; grid-template-columns: 1fr 1fr; gap: 20px;">';
    
    // Team 1 players
    html += '<div class="team-players">';
    html += '<h4>Starters</h4>';
    html += '<table style="width: 100%; border-collapse: collapse;">';
    html += '<thead><tr><th>Position</th><th>Player</th><th>Points</th></tr></thead>';
    html += '<tbody>';
    
    teams.team_1.starters.forEach(player => {
        html += `
            <tr style="background: ${player.points > 15 ? 'rgba(76, 175, 80, 0.1)' : player.points < 5 ? 'rgba(244, 67, 54, 0.1)' : 'transparent'};">
                <td style="padding: 5px; border: 1px solid #606060;">${player.position}</td>
                <td style="padding: 5px; border: 1px solid #606060;">${player.name}</td>
                <td style="padding: 5px; border: 1px solid #606060; text-align: right; font-weight: bold;">${player.points}</td>
            </tr>
        `;
    });
    
    html += '</tbody></table>';
    
    if (teams.team_1.bench && teams.team_1.bench.length > 0) {
        html += '<h4 style="margin-top: 15px;">Bench</h4>';
        html += '<table style="width: 100%; border-collapse: collapse;">';
        html += '<tbody>';
        teams.team_1.bench.forEach(player => {
            html += `
                <tr style="opacity: 0.7;">
                    <td style="padding: 5px; border: 1px solid #606060;">${player.position}</td>
                    <td style="padding: 5px; border: 1px solid #606060;">${player.name}</td>
                    <td style="padding: 5px; border: 1px solid #606060; text-align: right;">${player.points}</td>
                </tr>
            `;
        });
        html += '</tbody></table>';
    }
    html += '</div>';
    
    // Team 2 players
    html += '<div class="team-players">';
    html += '<h4>Starters</h4>';
    html += '<table style="width: 100%; border-collapse: collapse;">';
    html += '<thead><tr><th>Position</th><th>Player</th><th>Points</th></tr></thead>';
    html += '<tbody>';
    
    teams.team_2.starters.forEach(player => {
        html += `
            <tr style="background: ${player.points > 15 ? 'rgba(76, 175, 80, 0.1)' : player.points < 5 ? 'rgba(244, 67, 54, 0.1)' : 'transparent'};">
                <td style="padding: 5px; border: 1px solid #606060;">${player.position}</td>
                <td style="padding: 5px; border: 1px solid #606060;">${player.name}</td>
                <td style="padding: 5px; border: 1px solid #606060; text-align: right; font-weight: bold;">${player.points}</td>
            </tr>
        `;
    });
    
    html += '</tbody></table>';
    
    if (teams.team_2.bench && teams.team_2.bench.length > 0) {
        html += '<h4 style="margin-top: 15px;">Bench</h4>';
        html += '<table style="width: 100%; border-collapse: collapse;">';
        html += '<tbody>';
        teams.team_2.bench.forEach(player => {
            html += `
                <tr style="opacity: 0.7;">
                    <td style="padding: 5px; border: 1px solid #606060;">${player.position}</td>
                    <td style="padding: 5px; border: 1px solid #606060;">${player.name}</td>
                    <td style="padding: 5px; border: 1px solid #606060; text-align: right;">${player.points}</td>
                </tr>
            `;
        });
        html += '</tbody></table>';
    }
    html += '</div>';
    
    html += '</div>'; // End grid
    html += '</div>'; // End container
    
    return html;
}

function closeBreakdownModal() {
    const modal = document.getElementById('matchupBreakdownModal');
    if (modal) {
        modal.style.display = 'none';
        document.body.style.overflow = 'auto';
    }
}

