// modules/draft.js
/**
 * Draft Module
 * Handles draft board display and year selection
 */


function showDraftYear() {
    console.log('🏈 showDraftYear called');
    
    // Get draft data
    const draftData = getDraftData();
    
    // Check if draftData exists
    if (!draftData) {
        console.error('Draft data not loaded yet');
        return;
    }
    
    const yearSelect = document.getElementById('draftYearSelect');
    const selectedYear = yearSelect ? yearSelect.value : '2024';
    const container = document.getElementById('draftContainer');
    
    if (!container) {
        console.error('Draft container not found');
        return;
    }
    
    console.log('Selected draft year:', selectedYear);
    
    // Show loading state
    container.innerHTML = '<p style="text-align: center; color: #999;">Loading draft data...</p>';
    
    // Get draft info for selected year
    const yearData = draftData[selectedYear];
    
    if (!yearData) {
        container.innerHTML = `<p style="text-align: center; color: #ff6666;">No draft data available for ${selectedYear}</p>`;
        return;
    }
    
    // Create draft board
    createDraftBoard(yearData, container);
}

function createDraftBoard(draftInfo, container) {
    if (!draftInfo || !draftInfo.picks) {
        container.innerHTML = '<p style="text-align: center; color: #ff6666;">Invalid draft data</p>';
        return;
    }
    
    const picks = draftInfo.picks;
    const settings = draftInfo.settings || {};
    const rounds = settings.rounds || 15;
    const teams = settings.teams || 10;
    
    // Build draft board HTML
    let html = '<div class="draft-board-container" style="overflow-x: auto;">';
    html += '<h3 style="margin-bottom: 20px;">Draft Results - ' + (draftInfo.season || 'Unknown Season') + '</h3>';
    
    // Create table
    html += '<table class="draft-board" style="width: 100%; border-collapse: collapse;">';
    
    // Header row with team names
    html += '<thead><tr>';
    html += '<th style="padding: 10px; background: #404040; border: 1px solid #606060; position: sticky; left: 0; z-index: 10;">Round</th>';
    
    // Get team names for columns
    const teamNames = [];
    for (let i = 1; i <= teams; i++) {
        const firstPick = picks.find(p => p.draft_slot === i);
        const teamName = firstPick ? firstPick.picked_by : `Team ${i}`;
        teamNames.push(teamName);
        html += `<th style="padding: 10px; background: #404040; border: 1px solid #606060; min-width: 120px;">${teamName}</th>`;
    }
    
    html += '</tr></thead>';
    html += '<tbody>';
    
    // Create rows for each round
    for (let round = 1; round <= rounds; round++) {
        html += '<tr>';
        html += `<td style="padding: 10px; background: #404040; border: 1px solid #606060; font-weight: bold; position: sticky; left: 0; z-index: 5;">Round ${round}</td>`;
        
        // Add picks for each team in this round
        for (let slot = 1; slot <= teams; slot++) {
            const pick = picks.find(p => p.round === round && p.draft_slot === slot);
            
            if (pick && pick.metadata) {
                const player = pick.metadata;
                const positionClass = getPositionClass(player.position);
                
                html += `
                    <td style="padding: 5px; border: 1px solid #606060; background: rgba(0, 102, 204, 0.1);">
                        <div class="draft-pick ${positionClass}" style="text-align: center;">
                            <div style="font-weight: bold; font-size: 0.8em; color: ${getPositionColor(player.position)};">
                                ${player.position}
                            </div>
                            <div style="font-size: 0.9em; margin: 2px 0;">
                                ${player.first_name} ${player.last_name}
                            </div>
                            <div style="font-size: 0.8em; color: #999;">
                                ${player.team || 'FA'}
                            </div>
                            <div style="font-size: 0.7em; color: #666;">
                                Pick ${pick.pick_no}
                            </div>
                        </div>
                    </td>
                `;
            } else {
                html += '<td style="padding: 5px; border: 1px solid #606060; text-align: center; color: #666;">-</td>';
            }
        }
        
        html += '</tr>';
    }
    
    html += '</tbody></table>';
    html += '</div>';
    
    // Add draft summary
    html += '<div style="margin-top: 20px;">';
    html += '<h4>Draft Summary</h4>';
    html += '<div class="stats-grid" style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px; margin-top: 10px;">';
    
    // Position breakdown
    const positionCounts = {};
    picks.forEach(pick => {
        if (pick.metadata && pick.metadata.position) {
            positionCounts[pick.metadata.position] = (positionCounts[pick.metadata.position] || 0) + 1;
        }
    });
    
    Object.entries(positionCounts).sort((a, b) => b[1] - a[1]).forEach(([pos, count]) => {
        html += `
            <div class="stat-card" style="background: #2d2d2d; padding: 15px; border-radius: 10px; border: 1px solid #404040;">
                <h3 style="color: ${getPositionColor(pos)}; margin: 0;">${count}</h3>
                <p style="margin: 5px 0 0 0; color: #e0e0e0;">${pos}s drafted</p>
            </div>
        `;
    });
    
    html += '</div>';
    html += '</div>';
    
    container.innerHTML = html;
}

function getPositionClass(position) {
    const pos = position.toUpperCase();
    if (pos === 'QB') return 'position-qb';
    if (pos === 'RB') return 'position-rb';
    if (pos === 'WR') return 'position-wr';
    if (pos === 'TE') return 'position-te';
    if (pos === 'DEF') return 'position-def';
    if (pos === 'K') return 'position-k';
    return 'position-other';
}

function getPositionColor(position) {
    const pos = position.toUpperCase();
    if (pos === 'QB') return '#ff6b6b';
    if (pos === 'RB') return '#4ecdc4';
    if (pos === 'WR') return '#45b7d1';
    if (pos === 'TE') return '#f39c12';
    if (pos === 'DEF') return '#9b59b6';
    if (pos === 'K') return '#95a5a6';
    return '#e0e0e0';
}

// Export to window for panel switching
window.showDraftYear = showDraftYear;

// modules/playerJourney.js
/**
 * Player Journey Module
 * Handles player journey search and visualization
 */

let playerJourneyNetwork = null;

async function searchPlayerJourney() {
    const searchInput = document.getElementById('player-search');
    const playerName = searchInput ? searchInput.value.trim() : '';
    
    if (!playerName) {
        alert('Please enter a player name');
        return;
    }
    
    const resultsDiv = document.getElementById('player-journey-results');
    if (!resultsDiv) return;
    
    // Show loading state
    resultsDiv.innerHTML = '<p>Searching for player journey...</p>';
    
    try {
        // In a real implementation, this would fetch from an API
        // For now, we'll use a mock search
        displayLocalPlayerSearch(playerName);
    } catch (error) {
        console.error('Error searching player:', error);
        resultsDiv.innerHTML = '<p style="color: #ff6666;">Error searching for player. Please try again.</p>';
    }
}

function displayPlayerJourney(journeyData) {
    const resultsDiv = document.getElementById('player-journey-results');
    if (!resultsDiv) return;
    
    let html = '<div class="player-journey">';
    
    // Player header
    html += `
        <div class="player-header" style="display: flex; align-items: center; gap: 20px; margin-bottom: 20px;">
            <img src="${journeyData.image_url}" alt="${journeyData.player_name}" 
                 style="width: 80px; height: 80px; border-radius: 50%; object-fit: cover;"
                 onerror="this.src='https://sleepercdn.com/images/v2/icons/player_default.webp'">
            <div>
                <h3>${journeyData.player_name}</h3>
                <p>Position: ${journeyData.position} | Team: ${journeyData.team || 'FA'}</p>
                <p>Total Trades: ${journeyData.total_trades}</p>
            </div>
        </div>
    `;
    
    // Journey timeline
    html += '<div class="journey-timeline">';
    html += '<h4>Trade History</h4>';
    
    journeyData.journey.forEach((step, index) => {
        const isLastStep = index === journeyData.journey.length - 1;
        html += `
            <div class="timeline-step" style="margin-bottom: 20px; padding-left: 30px; border-left: 3px solid ${isLastStep ? 'transparent' : '#0066cc'};">
                <div class="step-marker" style="position: absolute; left: -8px; width: 16px; height: 16px; border-radius: 50%; background: #0066cc; border: 3px solid #1a1a1a;"></div>
                <div class="step-content" style="background: #2d2d2d; padding: 15px; border-radius: 8px;">
                    <div style="display: flex; justify-content: space-between; align-items: start;">
                        <div>
                            <h5 style="margin: 0 0 5px 0; color: #0066cc;">${step.team}</h5>
                            <p style="margin: 0; color: #999; font-size: 0.9em;">${step.acquired_date || 'Original Team'}</p>
                        </div>
                        ${step.traded_date ? `
                            <div style="text-align: right;">
                                <p style="margin: 0; color: #ff6666; font-size: 0.9em;">Traded: ${step.traded_date}</p>
                                <p style="margin: 0; color: #999; font-size: 0.8em;">To: ${step.traded_to}</p>
                            </div>
                        ` : '<span style="color: #66ff66;">Current Team</span>'}
                    </div>
                    ${step.trade_details ? `
                        <div style="margin-top: 10px; padding-top: 10px; border-top: 1px solid #404040;">
                            <p style="margin: 0; font-size: 0.9em;">Trade Details: ${step.trade_details}</p>
                        </div>
                    ` : ''}
                </div>
            </div>
        `;
    });
    
    html += '</div>';
    
    // Network visualization
    html += '<div class="journey-network" style="margin-top: 30px;">';
    html += '<h4>Team Network</h4>';
    html += '<div id="player-journey-network" style="height: 400px; background: #2d2d2d; border: 1px solid #404040; border-radius: 8px;"></div>';
    html += '</div>';
    
    html += '</div>';
    
    resultsDiv.innerHTML = html;
    
    // Create network visualization
    setTimeout(() => createPlayerJourneyNetwork(journeyData), 100);
}

function createPlayerJourneyNetwork(journeyData) {
    const container = document.getElementById('player-journey-network');
    if (!container) return;
    
    // Create nodes for each team
    const nodes = new vis.DataSet();
    const edges = new vis.DataSet();
    
    const teamSet = new Set();
    journeyData.journey.forEach(step => {
        teamSet.add(step.team);
        if (step.traded_to) {
            teamSet.add(step.traded_to);
        }
    });
    
    // Add nodes
    let nodeId = 0;
    const teamToNodeId = {};
    teamSet.forEach(team => {
        teamToNodeId[team] = nodeId;
        nodes.add({
            id: nodeId,
            label: team,
            color: {
                background: team === journeyData.current_team ? '#66ff66' : '#0066cc',
                border: team === journeyData.current_team ? '#44dd44' : '#004499'
            }
        });
        nodeId++;
    });
    
    // Add edges for trades
    journeyData.journey.forEach((step, index) => {
        if (step.traded_to) {
            edges.add({
                from: teamToNodeId[step.team],
                to: teamToNodeId[step.traded_to],
                label: step.traded_date,
                arrows: 'to',
                color: {
                    color: '#666666',
                    highlight: '#0066cc'
                }
            });
        }
    });
    
    const data = { nodes, edges };
    
    const options = {
        nodes: {
            shape: 'dot',
            size: 30,
            font: {
                size: 14,
                color: '#e0e0e0'
            }
        },
        edges: {
            font: {
                size: 12,
                color: '#999999',
                align: 'middle'
            },
            smooth: {
                type: 'cubicBezier',
                forceDirection: 'horizontal',
                roundness: 0.4
            }
        },
        layout: {
            hierarchical: {
                direction: 'LR',
                sortMethod: 'directed',
                levelSeparation: 200
            }
        },
        interaction: {
            hover: true,
            tooltipDelay: 200
        },
        physics: false
    };
    
    playerJourneyNetwork = new vis.Network(container, data, options);
    
    // Add click handler
    playerJourneyNetwork.on('click', function(params) {
        if (params.edges.length > 0) {
            const edgeId = params.edges[0];
            const edge = edges.get(edgeId);
            
            // Find the trade details
            journeyData.journey.forEach(step => {
                if (step.traded_date === edge.label) {
                    showJourneyStepDetails(step, journeyData);
                }
            });
        }
    });
}

function showJourneyStepDetails(stepData, journeyData) {
    // Create a modal or update a details panel with trade information
    const detailsHtml = `
        <div style="background: #2d2d2d; padding: 20px; border-radius: 8px; margin-top: 20px;">
            <h4>Trade Details</h4>
            <p><strong>Date:</strong> ${stepData.traded_date}</p>
            <p><strong>From:</strong> ${stepData.team}</p>
            <p><strong>To:</strong> ${stepData.traded_to}</p>
            ${stepData.trade_details ? `<p><strong>Details:</strong> ${stepData.trade_details}</p>` : ''}
        </div>
    `;
    
    // You could append this to the results or show in a modal
    const resultsDiv = document.getElementById('player-journey-results');
    const existingDetails = resultsDiv.querySelector('.trade-details-panel');
    if (existingDetails) {
        existingDetails.innerHTML = detailsHtml;
    } else {
        const detailsPanel = document.createElement('div');
        detailsPanel.className = 'trade-details-panel';
        detailsPanel.innerHTML = detailsHtml;
        resultsDiv.appendChild(detailsPanel);
    }
}

function displayLocalPlayerSearch(playerName) {
    const resultsDiv = document.getElementById('player-journey-results');
    if (!resultsDiv) return;
    
    // For now, show a message that we need to search through trades
    // In a real implementation, this would search through the trade data
    resultsDiv.innerHTML = `
        <div style="background: #2d2d2d; padding: 20px; border-radius: 8px;">
            <h4>Player Search: ${playerName}</h4>
            <p>To see player journeys, the system needs to process all trade data to track player movements.</p>
            <p>This feature would show:</p>
            <ul style="margin-left: 20px;">
                <li>Complete trade history for the player</li>
                <li>Teams they've been on</li>
                <li>Trade partners and dates</li>
                <li>Visual network of their journey</li>
            </ul>
            <p style="margin-top: 15px; color: #999;">
                Try searching for players you know have been traded multiple times in your league.
            </p>
        </div>
    `;
}

// Export to window for onclick handlers
window.searchPlayerJourney = searchPlayerJourney;

// modules/externalData.js
/**
 * External Data Module
 * Handles loading and managing external script data
 * (matchupBreakdowns, leagueIdByYear, draftData)
 */

// These will be populated by external scripts
let matchupBreakdowns = null;
let leagueIdByYear = null;
let draftData = null;

// Check if data is already loaded from external scripts
function checkExternalData() {
    if (typeof window.matchupBreakdowns !== 'undefined') {
        matchupBreakdowns = window.matchupBreakdowns;
        console.log('✅ Matchup breakdowns loaded');
    }
    
    if (typeof window.leagueIdByYear !== 'undefined') {
        leagueIdByYear = window.leagueIdByYear;
        console.log('✅ League mapping loaded');
    }
    
    if (typeof window.draftData !== 'undefined') {
        draftData = window.draftData;
        console.log('✅ Draft data loaded');
    }
}

// Getters for the data
function getMatchupBreakdowns() {
    if (!matchupBreakdowns) {
        checkExternalData();
    }
    return matchupBreakdowns;
}

function getLeagueIdByYear() {
    if (!leagueIdByYear) {
        checkExternalData();
    }
    return leagueIdByYear;
}

function getDraftData() {
    if (!draftData) {
        checkExternalData();
    }
    return draftData;
}

// Initialize on load
setTimeout(checkExternalData, 100);

// Also make them available globally for backward compatibility
window.getMatchupBreakdowns = getMatchupBreakdowns;
window.getLeagueIdByYear = getLeagueIdByYear;
window.getDraftData = getDraftData;

// main.js
/**
 * Main Application Module
 * Initializes all modules and sets up the application
 */

// Import all modules










// Initialize the application when DOM is ready
document.addEventListener('DOMContentLoaded', function() {
    console.log('🚀 Initializing Eazy Pickens application...');
    
    // Check for external data first
    checkExternalData();
    
    // Initialize Firebase
    initializeFirebase();
    
    // Initialize trade history features
    initializeTradeHistory();
    
    // Load matchup breakdowns if available
    loadMatchupBreakdowns();
    
    // Set up refresh button for ratings
    const refreshButton = document.querySelector('button[onclick="refreshTradingSummary()"]');
    if (refreshButton) {
        refreshButton.onclick = function() {
            manualRefreshRatings(false);
        };
    }
    
    // Initialize with overview panel
    if (typeof showPanel === 'function') {
        showPanel('overview');
    }
    
    // Set up any global event listeners
    setupGlobalEventListeners();
    
    // Check for saved preferences
    loadUserPreferences();
    
    console.log('✅ Application initialized successfully');
});

function setupGlobalEventListeners() {
    // Handle keyboard shortcuts
    document.addEventListener('keydown', function(e) {
        // Escape key closes modals
        if (e.key === 'Escape') {
            if (typeof closeTradeModal === 'function') closeTradeModal();
            if (typeof closeBreakdownModal === 'function') closeBreakdownModal();
        }
    });
    
    // Handle window resize for responsive elements
    let resizeTimeout;
    window.addEventListener('resize', function() {
        clearTimeout(resizeTimeout);
        resizeTimeout = setTimeout(function() {
            // Re-initialize any size-dependent visualizations
            const activePanel = document.querySelector('.visualization-panel.active');
            if (activePanel) {
                const panelId = activePanel.id;
                if (panelId === 'network-panel' && typeof initNetworkGraph === 'function') {
                    initNetworkGraph();
                } else if (panelId === 'overview-panel' && typeof initMonthlyChart === 'function') {
                    initMonthlyChart();
                }
            }
        }, 250);
    });
}

function loadUserPreferences() {
    // Load saved preferences from localStorage
    const preferences = {
        showPlayerBreakdowns: localStorage.getItem('showPlayerBreakdowns') === 'true',
        userName: localStorage.getItem('userName'),
        lastPanel: localStorage.getItem('lastPanel') || 'overview'
    };
    
    // Apply preferences
    const breakdownCheckbox = document.getElementById('toggleBreakdowns');
    if (breakdownCheckbox && preferences.showPlayerBreakdowns) {
        breakdownCheckbox.checked = true;
        if (typeof togglePlayerBreakdowns === 'function') {
            togglePlayerBreakdowns();
        }
    }
    
    // You could also restore the last viewed panel, but for now we always start with overview
    // to ensure consistent initial state
}

// Export any functions that need to be globally available
window.APP = {
    version: '1.0.0',
    initialized: true,
    modules: {
        firebase: { initializeFirebase, manualRefreshRatings },
        tradeHistory: { initializeTradeHistory },
        matchups: { loadMatchupBreakdowns }
    }
};
